import pandas as pd
import numpy as np

file_path = '/data/programme_monthly_spend.xlsx'
df_raw = pd.read_excel(file_path, sheet_name=0, header=None)

start_row = 4
data = []
for i in range(start_row, df_raw.shape[0]):
    row = df_raw.iloc[i]
    prog_code = row[0]
    if pd.isna(prog_code):
        continue
    code_str = str(prog_code).strip()
    if code_str.upper() == 'PORTFOLIO TOTAL':
        break
    # extract monthly values columns 4-9
    monthly_vals = []
    for col in range(4,10):
        val = row[col]
        # handle various missing representations
        if pd.isna(val):
            monthly_vals.append(0)
        else:
            val_str = str(val).strip()
            if val_str in ['-', '–', '']:
                monthly_vals.append(0)
            else:
                # try convert to numeric
                try:
                    num = float(val_str.replace(',',''))
                    monthly_vals.append(num)
                except:
                    monthly_vals.append(0)
    data.append(monthly_vals)

monthly_array = np.array(data, dtype=float)
print('shape', monthly_array.shape)
print('sum per programme', monthly_array.sum(axis=1))
print('total sum monthly', monthly_array.sum())
# compare to six-month total column
six_month_totals = []
for i in range(start_row, df_raw.shape[0]):
    row = df_raw.iloc[i]
    prog_code = row[0]
    if pd.isna(prog_code):
        continue
    code_str = str(prog_code).strip()
    if code_str.upper() == 'PORTFOLIO TOTAL':
        break
    val = row[10]
    if pd.isna(val):
        six_month_totals.append(0)
    else:
        try:
            six_month_totals.append(float(val))
        except:
            six_month_totals.append(0)
print('sum six-month totals', sum(six_month_totals))
